class Translator:
    def __init__(self, language='EN'):
        self.language = language

    def text(self, text, **values):
        translated = FR.get(text, text) if self.language == 'FR' and isinstance(text, str) else text
        return translated.format(**values) if values else translated


def localize_frame(frame, translate):
    # These columns contain user input: do not translate their values.
    user_columns = {'Reference', 'SME', 'Buyer'}
    result = frame.copy()
    for column in result.columns:
        if column not in user_columns:
            result[column] = result[column].map(lambda value: translate(value) if isinstance(value, str) else value)
    return result.rename(columns=translate)

